<?php
namespace App\Http\Controllers;
use App\Jobs\RunScrapingJob;
use App\Models\{ProspectingJob,LeadList};
use Illuminate\Http\Request;
class ProspectingController extends Controller {
 public function __invoke(Request $r){$html=file_get_contents(resource_path('views/prospecting.html'));$shell=view('components.scraper-sidebar')->render();$sv=filemtime(public_path('scraper-shell.css'));$pv=filemtime(public_path('prospecting-shell.css'));$av=filemtime(public_path('app/app.js'));$opts=$r->user()->leadLists()->orderBy('name')->get()->map(fn($l)=>'<option value="'.$l->id.'">'.e($l->name).'</option>')->implode('');$html=str_replace('<body>','<body class="prospecting-embedded">'.$shell,$html);$html=str_replace('<aside class="sidebar glass" id="panel">','<aside class="sidebar glass prospecting-functional-panel" id="panel">',$html);$html=str_replace('<button id="submit"','<label class="lead-list-picker">Lista de Leads<select id="lead_list_id"><option value="">Sem lista</option>'.$opts.'</select></label><button id="submit"',$html);$html=str_replace('</head>','<meta name="csrf-token" content="'.e(csrf_token()).'"><link rel="stylesheet" href="'.asset('scraper-shell.css').'?v='.$sv.'"><link rel="stylesheet" href="'.asset('prospecting-shell.css').'?v='.$pv.'"></head>',$html);$html=str_replace('/app/app.js','/app/app.js?v='.$av,$html);return response($html)->header('Content-Type','text/html; charset=UTF-8')->header('Cache-Control','no-store, private')->cookie('XSRF-TOKEN',csrf_token(),120,'/',null,app()->environment('production'),false,false,'lax');}
 public function store(Request $r){$d=$r->validate(['keywords'=>'required|array|min:1','keywords.*'=>'string|max:255','location'=>'nullable|string|max:255','latitude'=>'nullable|numeric','longitude'=>'nullable|numeric','search_parameters'=>'nullable|array','lead_list_id'=>'nullable|integer']);$l=$d['lead_list_id']??null;if($l&&!LeadList::where('id',$l)->where('user_id',$r->user()->id)->exists())abort(422);$j=$r->user()->prospectingJobs()->create(['lead_list_id'=>$l,'keywords'=>$d['keywords'],'location'=>$d['location']??null,'latitude'=>$d['latitude']??null,'longitude'=>$d['longitude']??null,'search_parameters'=>$d['search_parameters']??[],'status'=>'pending']);RunScrapingJob::dispatch($j->id);return response()->json(['id'=>$j->id,'status'=>$j->status],202);}
 public function index(Request $r){return $r->user()->prospectingJobs()->latest()->paginate(20);}
 public function show(Request $r,ProspectingJob $job){$this->authorize('view',$job);return $job->load('leads');}
 public function legacyIndex(Request $r){return response()->json($r->user()->prospectingJobs()->latest()->get()->map(fn($j)=>['ID'=>$j->id,'Name'=>$j->location?:'Busca','Date'=>$j->created_at,'Status'=>$j->status,'Data'=>array_merge($j->search_parameters??[],['keywords'=>$j->keywords,'lat'=>$j->latitude,'lon'=>$j->longitude,'radius'=>($j->search_parameters['radius']??0),'depth'=>($j->search_parameters['depth']??5),'email'=>($j->search_parameters['email']??false)]),'lead_list_id'=>$j->lead_list_id]));}
 public function legacyStore(Request $r){$d=$r->validate(['keywords'=>'required|array|min:1','lat'=>'required','lon'=>'required','max_time'=>'required|integer','depth'=>'nullable|integer','radius'=>'nullable|integer','email'=>'nullable|boolean','name'=>'nullable|string','lead_list_id'=>'nullable|integer']);$l=$d['lead_list_id']??null;if($l&&!LeadList::where('id',$l)->where('user_id',$r->user()->id)->exists())abort(422);$j=$r->user()->prospectingJobs()->create(['lead_list_id'=>$l,'keywords'=>$d['keywords'],'location'=>$d['name']??null,'latitude'=>$d['lat'],'longitude'=>$d['lon'],'search_parameters'=>$d,'status'=>'pending']);RunScrapingJob::dispatch($j->id);return response()->json(['id'=>$j->id],201);}
 public function legacyStatus(Request $r,ProspectingJob $job){$this->authorize('view',$job);return response()->json(['ID'=>$job->id,'Name'=>$job->location,'Date'=>$job->created_at,'Status'=>$job->status,'Data'=>$job->search_parameters,'lead_list_id'=>$job->lead_list_id]);}
 public function legacyDownload(Request $r,ProspectingJob $job){$this->authorize('view',$job);$rows=$job->leads()->get();$head=['title','phone','emails','website','category','address','latitude','longitude','place_id','review_rating','review_count'];$out=fopen('php://temp','r+');fputcsv($out,$head);foreach($rows as $lead){$raw=$lead->raw_data??[];fputcsv($out,array_map(fn($k)=>$raw[$k]??match($k){'title'=>$lead->name,'phone'=>$lead->phone,'emails'=>$lead->email,'website'=>$lead->website,'category'=>$lead->category,'address'=>$lead->address,'latitude'=>$lead->latitude,'longitude'=>$lead->longitude,'place_id'=>$lead->external_place_id,default=>''},$head));}rewind($out);return response(stream_get_contents($out),200,['Content-Type'=>'text/csv','Content-Disposition'=>'attachment; filename="kaizen-job-'.$job->id.'.csv"']);}
 public function legacyDestroy(Request $r,ProspectingJob $job){$this->authorize('delete',$job);if(in_array($job->status,['working','pending'],true)||($job->status==='unknown'&&filled($job->scraper_job_id))){$job->update(['status'=>'cancel_requested','cancel_requested_at'=>now()]);return response()->json(['status'=>'cancel_requested'],202);}$job->delete();return response()->noContent();}
}
